const LAB_TAU:f32 = 6.28318530718;
fn labReflect01(v:f32)->f32 { return 1.0-abs(2.0*fract(v*0.5)-1.0); }
fn labMain(uv: vec2f) -> vec4f {
  let base=labInput(uv);
  let aspect=labAspect();
  let p=(uv-vec2f(0.5))*vec2f(aspect,1.0);
  let r=max(length(p),0.0001);
  let wave=sin(r*labParam(1)*LAB_TAU-labTime()*labParam(2));
  let falloff=smoothstep(0.72,0.08,r);
  let q=uv+normalize(p)/vec2f(aspect,1.0)*wave*labParam(0)*falloff;
  let sample=labInput(vec2f(labReflect01(q.x),labReflect01(q.y)));
  return vec4f(mix(base.rgb,sample.rgb,0.85),base.a);
}

const LAB_TAU:f32 = 6.28318530718;
fn labStripe(p:vec2f, a:f32, spacing:f32, t:f32)->f32 {
  let axis=vec2f(cos(a),sin(a));
  return 0.5+0.5*cos(dot(p,axis)*spacing+t);
}
fn labMain(uv: vec2f) -> vec4f {
  let p=(uv-vec2f(0.5))*vec2f(labAspect(),1.0);
  let spacing=labParam(0);
  let angle=labParam(1);
  let t=labTime()*labParam(2);
  let a=labStripe(p,angle,spacing,t);
  let b=labStripe(p,-angle+0.24,spacing*1.07,-t*0.73);
  let lines=smoothstep(0.42,0.78,a)*smoothstep(0.35,0.82,b);
  let glow=pow(abs(a-b),0.55);
  let col=mix(vec3f(0.02,0.025,0.03),vec3f(0.15,0.75,0.9),lines)+vec3f(0.95,0.42,0.18)*glow*0.45;
  return vec4f(col,1.0);
}

const LAB_TAU: f32 = 6.28318530718;

fn labHash11(x: f32) -> f32 {
  return fract(sin(x * 127.1) * 43758.5453);
}

fn labNoise1D(x: f32) -> f32 {
  let i = floor(x);
  let f = fract(x);
  let u = f * f * (3.0 - 2.0 * f);
  return mix(labHash11(i), labHash11(i + 1.0), u);
}

fn labRidgeFbm(x: f32, rugged: f32) -> f32 {
  var v: f32 = 0.0;
  var a: f32 = 0.55;
  var freq: f32 = 1.0;
  for (var i = 0; i < 5; i++) {
    let n = labNoise1D(x * freq);
    let peak = 1.0 - abs(n - 0.5) * 2.0;
    v = v + pow(max(peak, 0.0), rugged) * a;
    freq = freq * 2.15;
    a = a * 0.48;
  }
  return v;
}

fn labMain(uv: vec2f) -> vec4f {
  let aspect = labAspect();
  let p = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let haze = labParam(0);
  let glow = labParam(1);
  let t = labTime() * labParam(2) * 0.05;
  let rugged = labParam(3);

  let skyY = clamp(p.y + 0.5, 0.0, 1.0);
  let skyTop = vec3f(0.06, 0.06, 0.18);
  let skyMid = vec3f(0.48, 0.16, 0.36);
  let skyLow = vec3f(0.96, 0.46, 0.28);
  let skyHorizon = vec3f(1.0, 0.78, 0.52);

  var sky = mix(skyHorizon, skyLow, smoothstep(0.2, 0.55, skyY));
  sky = mix(sky, skyMid, smoothstep(0.55, 0.8, skyY));
  sky = mix(sky, skyTop, smoothstep(0.8, 1.0, skyY));

  let sunPos = vec2f(0.18 * aspect, 0.05);
  let sunDist = length(p - sunPos);
  let sunGlow = exp(-sunDist * 2.8) * vec3f(1.0, 0.72, 0.42) * glow;
  sky = sky + sunGlow;

  var col = sky;

  let y0 = -0.02 + 0.22 * labRidgeFbm(p.x * 0.9 + t * 0.15 + 1.2, rugged * 0.9);
  let col0 = mix(vec3f(0.42, 0.22, 0.38), vec3f(0.85, 0.48, 0.4), haze * 0.6);
  let rim0 = smoothstep(0.015, 0.0, abs(p.y - y0)) * vec3f(1.0, 0.75, 0.55) * glow * 0.6;
  if (p.y < y0) { col = col0 + rim0; }

  let y1 = -0.12 + 0.25 * labRidgeFbm(p.x * 1.4 - t * 0.28 + 5.7, rugged);
  let col1 = mix(vec3f(0.24, 0.12, 0.26), vec3f(0.72, 0.34, 0.36), haze * 0.4);
  let rim1 = smoothstep(0.018, 0.0, abs(p.y - y1)) * vec3f(1.0, 0.68, 0.5) * glow * 0.7;
  if (p.y < y1) { col = col1 + rim1; }

  let y2 = -0.24 + 0.28 * labRidgeFbm(p.x * 2.0 + t * 0.45 + 11.3, rugged * 1.1);
  let col2 = mix(vec3f(0.12, 0.07, 0.18), vec3f(0.48, 0.2, 0.28), haze * 0.25);
  let rim2 = smoothstep(0.02, 0.0, abs(p.y - y2)) * vec3f(0.95, 0.55, 0.45) * glow * 0.5;
  if (p.y < y2) { col = col2 + rim2; }

  let y3 = -0.38 + 0.30 * labRidgeFbm(p.x * 2.8 - t * 0.65 + 23.1, rugged * 1.2);
  let col3 = vec3f(0.04, 0.03, 0.08);
  if (p.y < y3) { col = col3; }

  let mist = smoothstep(0.1, -0.45, p.y) * haze * 0.35;
  col = mix(col, vec3f(0.85, 0.55, 0.5), mist);

  return vec4f(col, 1.0);
}

fn labSq(v: f32) -> f32 { return v * v; }
fn labCloudNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = fract(sin(dot(i, vec2f(12.9898, 78.233))) * 43758.5453);
  let b = fract(sin(dot(i + vec2f(1.0, 0.0), vec2f(12.9898, 78.233))) * 43758.5453);
  let c = fract(sin(dot(i + vec2f(0.0, 1.0), vec2f(12.9898, 78.233))) * 43758.5453);
  let d = fract(sin(dot(i + vec2f(1.0, 1.0), vec2f(12.9898, 78.233))) * 43758.5453);
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn labMountainProfile(x: f32) -> f32 {
  let p1 = exp(-labSq((x - 0.2) * 4.5)) * 0.38;
  let p2 = exp(-labSq((x + 0.45) * 3.4)) * 0.32;
  let p3 = exp(-labSq((x - 0.72) * 5.0)) * 0.26;
  let p4 = exp(-labSq((x + 0.85) * 4.2)) * 0.28;
  let ridges = 0.035 * sin(x * 24.0) + 0.018 * cos(x * 52.0);
  return -0.06 + p1 + p2 + p3 + p4 + ridges;
}

fn labStars(p: vec2f, twinkleRate: f32, t: f32) -> vec3f {
  let grid = p * 42.0;
  let i = floor(grid);
  let f = fract(grid);
  let rand = fract(sin(dot(i, vec2f(12.9898, 78.233))) * 43758.5453);
  let starPos = vec2f(
    fract(sin(rand * 91.34) * 43758.5453),
    fract(cos(rand * 53.21) * 43758.5453)
  );
  let d = length(f - starPos);
  let bright = pow(rand, 18.0) * 12.0;
  let tw = 0.5 + 0.5 * sin(t * twinkleRate * 3.0 + rand * 6.28);
  let star = smoothstep(0.08, 0.01, d) * bright * tw;
  let tint = mix(vec3f(0.7, 0.85, 1.0), vec3f(1.0, 0.9, 0.75), fract(rand * 7.0));
  return tint * star;
}

fn labEvaluateSky(p: vec2f, milkyWay: f32, twinkle: f32, t: f32) -> vec3f {
  let sky = mix(vec3f(0.012, 0.02, 0.05), vec3f(0.005, 0.008, 0.02), clamp(p.y + 0.5, 0.0, 1.0));

  let mwCoord = p.x * 0.707 + p.y * 0.707;
  let mwBand = exp(-labSq((mwCoord - 0.12) * 3.2));
  let mwNoise = labCloudNoise(p * 5.0) * 0.6 + labCloudNoise(p * 12.0) * 0.4;
  let mwGlow = mwBand * mwNoise * milkyWay * vec3f(0.32, 0.42, 0.78);

  let stars = labStars(p, twinkle, t);
  var col = sky + mwGlow + stars;

  let mY = labMountainProfile(p.x);
  if (p.y < mY) {
    let isSnow = step(mY - 0.14, p.y) * (0.6 + 0.4 * sin(p.x * 35.0 + p.y * 25.0));
    col = mix(vec3f(0.06, 0.07, 0.12), vec3f(0.55, 0.65, 0.85), isSnow * 0.5);
  }

  return col;
}

fn labMain(uv: vec2f) -> vec4f {
  let aspect = labAspect();
  let p = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let milkyWay = labParam(0);
  let twinkle = labParam(1);
  let waterRipples = labParam(2);
  let reflection = labParam(3);

  let waterY = -0.08;
  let t = labTime();

  var col = vec3f(0.0);

  if (p.y >= waterY) {
    col = labEvaluateSky(p, milkyWay, twinkle, t);
  } else {
    let depth = waterY - p.y;
    let wave1 = sin(p.x * 30.0 + depth * 55.0 - t * 1.8);
    let wave2 = cos(p.x * 20.0 - depth * 35.0 + t * 1.3);
    let wave = (wave1 + wave2) * 0.5;

    let sampleP = vec2f(
      p.x + wave * 0.012 * waterRipples,
      waterY + depth + wave * 0.02 * waterRipples
    );

    let reflected = labEvaluateSky(sampleP, milkyWay, twinkle, t);
    let lakeWater = vec3f(0.01, 0.025, 0.05);

    col = mix(lakeWater, reflected, reflection * 0.85);

    let shimmer = pow(max(0.0, wave), 4.0) * 0.15 * waterRipples;
    col = col + vec3f(0.6, 0.75, 0.95) * shimmer;
  }

  return vec4f(col, 1.0);
}

fn labHash(p: vec2f) -> f32 {
  let h = dot(p, vec2f(127.1, 311.7));
  return fract(sin(h) * 43758.5453123);
}

fn labNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = labHash(i);
  let b = labHash(i + vec2f(1.0, 0.0));
  let c = labHash(i + vec2f(0.0, 1.0));
  let d = labHash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn labFbm(p: vec2f) -> f32 {
  var v = 0.5 * labNoise(p);
  let p2 = p * 2.02 + vec2f(13.1, 17.4);
  v += 0.25 * labNoise(p2);
  let p3 = p2 * 2.03 + vec2f(27.3, 41.2);
  v += 0.125 * labNoise(p3);
  return v;
}

fn labMain(uv: vec2f) -> vec4f {
  let aspect = labAspect();
  let p = (uv - vec2f(0.5)) * vec2f(aspect, 1.0);
  let speed = labParam(0) * 0.12;
  let t = labTime() * speed;
  let valleyFlow = p.y - t * max(0.2, 1.0 - 0.45 * p.x * p.x);

  let warp = labFbm(vec2f(p.x * 2.2, valleyFlow * 1.6));
  let scale = labParam(1);
  let depthParam = labParam(2);

  let chevron = valleyFlow - 0.28 * p.x * p.x;
  let crackPhase = (chevron + warp * 0.28) * scale * 2.6;
  let fissureWave = sin(crackPhase * 6.2831853);
  let fissure = pow(smoothstep(0.48, 0.98, fissureWave), 1.6) * depthParam;

  let wallShear = smoothstep(0.2, 0.68, abs(p.x));
  let shearPhase = (valleyFlow * 2.0 + sign(p.x) * p.x * 1.7 + warp * 0.32) * scale * 2.1;
  let shearCrack = pow(smoothstep(0.52, 0.98, sin(shearPhase * 6.2831853)), 1.8) * wallShear * depthParam;

  let totalCrevasse = clamp(max(fissure, shearCrack), 0.0, 1.0);

  let deepAbyss = vec3f(0.012, 0.035, 0.08);
  let iceGlow = vec3f(0.04, 0.68, 0.86);
  let crevasseCol = mix(iceGlow, deepAbyss, smoothstep(0.35, 0.95, totalCrevasse));

  let surfaceSnow = vec3f(0.91, 0.95, 0.98);
  let blueIce = vec3f(0.56, 0.74, 0.88);
  let surfaceWaves = sin(p.x * 11.0 + valleyFlow * 3.8) * 0.5 + 0.5;
  var surfaceCol = mix(blueIce, surfaceSnow, surfaceWaves * 0.55 + 0.45 * warp);

  let moraine = smoothstep(0.48, 0.85, abs(p.x)) * (0.45 + 0.55 * labNoise(vec2f(p.x * 24.0, valleyFlow * 6.0)));
  surfaceCol = mix(surfaceCol, vec3f(0.34, 0.32, 0.31), moraine * 0.75);

  let lipHighlight = smoothstep(0.04, 0.16, totalCrevasse) * smoothstep(0.32, 0.12, totalCrevasse);
  let rimCol = vec3f(0.96, 0.99, 1.0);

  var col = mix(surfaceCol, crevasseCol, smoothstep(0.08, 0.65, totalCrevasse));
  col += rimCol * lipHighlight * 0.65;

  let meltWave = sin(valleyFlow * 7.5 + p.x * 3.5 + warp * 2.2);
  let meltPool = smoothstep(0.72, 0.9, meltWave) * (1.0 - totalCrevasse) * (1.0 - moraine);
  col = mix(col, vec3f(0.01, 0.86, 0.92), meltPool * 0.5);

  let dist = length(p);
  col *= smoothstep(1.25, 0.35, dist);

  return vec4f(col, 1.0);
}
